import time
import json
import uuid
from datetime import datetime

# 留言資料儲存在記憶體中
messages = []


def handle(method, path, body):
    if method == "GET" and path == "/messages":
        # 按時間順序排列，最新的在最上面
        sorted_messages = sorted(messages, key=lambda x: x["timestamp"], reverse=True)
        return (200, sorted_messages)

    elif method == "POST" and path == "/messages":
        try:
            data = json.loads(body.decode())
            content = data.get("content")
            if not content:
                return (400, {"error": "內容不能為空"})

            # 建立新的留言
            new_message = {
                "id": str(uuid.uuid4()),
                "content": content,
                "timestamp": datetime.now().isoformat(),
                "likes": 0
            }

            messages.append(new_message)
            return (201, new_message)
        except json.JSONDecodeError:
            return (400, {"error": "無效的JSON格式"})

    elif method == "PUT" and path.startswith("/messages/") and path.endswith("/like"):
        # 提取留言ID
        message_id = path.split("/")[3]

        for message in messages:
            if message["id"] == message_id:
                message["likes"] += 1
                return (200, message)

        return (404, {"error": "留言未找到"})

    elif method == "DELETE" and path.startswith("/messages/"):
        # 提取留言ID
        message_id = path.split("/")[3]

        for i, message in enumerate(messages):
            if message["id"] == message_id:
                del messages[i]
                return (200, {"message": "留言已刪除"})

        return (404, {"error": "留言未找到"})

    elif method == "GET" and path == "/messages/sort/likes":
        # 按讚數排序，讚數多的在最上面
        sorted_messages = sorted(messages, key=lambda x: x["likes"], reverse=True)
        return (200, sorted_messages)

    else:
        return (404, {"error": "路徑不存在"})

