document.addEventListener('DOMContentLoaded', () => {
    const messageForm = document.getElementById('messageForm');
    const messageInput = document.getElementById('messageInput');
    const messagesContainer = document.getElementById('messagesContainer');
    const sortTimeBtn = document.getElementById('sortTimeBtn');
    const sortLikesBtn = document.getElementById('sortLikesBtn');

    let currentSort = 'time'; // 'time' or 'likes'

    // 獲取所有留言並顯示
    async function loadMessages() {
        try {
            let url = 'api/messages';
            if (currentSort === 'likes') {
                url = 'api/messages/sort/likes';
            }

            const response = await fetch(url);
            const messages = await response.json();
            displayMessages(messages);
        } catch (error) {
            console.error('獲取留言失敗:', error);
        }
    }

    // 顯示留言列表
    function displayMessages(messages) {
        messagesContainer.innerHTML = '';

        if (messages.length === 0) {
            messagesContainer.innerHTML = '<p>目前沒有留言</p>';
            return;
        }

        messages.forEach(message => {
            const messageElement = document.createElement('div');
            messageElement.className = 'message';
            messageElement.innerHTML = `
                <p>${message.content}</p>
                <div class="message-info">
                    <span>時間: ${new Date(message.timestamp).toLocaleString('zh-TW')}</span>
                    <div class="actions">
                        <button onclick="likeMessage('${message.id}')" class="like-btn">👍 ${message.likes}</button>
                        <button onclick="deleteMessage('${message.id}')" class="delete-btn">🗑️</button>
                    </div>
                </div>
            `;
            messagesContainer.appendChild(messageElement);
        });
    }

    // 新增留言
    messageForm.addEventListener('submit', async (e) => {
        e.preventDefault();

        const content = messageInput.value.trim();
        if (!content) return;

        try {
            const response = await fetch('api/messages', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ content })
            });

            if (response.ok) {
                messageInput.value = '';
                loadMessages(); // 重新載入留言
            } else {
                console.error('新增留言失敗');
            }
        } catch (error) {
            console.error('網路錯誤:', error);
        }
    });

    // 按讚功能
    window.likeMessage = async (id) => {
        try {
            const response = await fetch(`api/messages/${id}/like`, {
                method: 'PUT'
            });

            if (response.ok) {
                loadMessages(); // 重新載入留言
            } else {
                console.error('按讚失敗');
            }
        } catch (error) {
            console.error('網路錯誤:', error);
        }
    };

    // 刪除留言
    window.deleteMessage = async (id) => {
        if (!confirm('確定要刪除這則留言嗎？')) return;

        try {
            const response = await fetch(`api/messages/${id}`, {
                method: 'DELETE'
            });

            if (response.ok) {
                loadMessages(); // 重新載入留言
            } else {
                console.error('刪除留言失敗');
            }
        } catch (error) {
            console.error('網路錯誤:', error);
        }
    };

    // 切換時間排序
    sortTimeBtn.addEventListener('click', () => {
        currentSort = 'time';
        loadMessages();
    });

    // 切換讚數排序
    sortLikesBtn.addEventListener('click', () => {
        currentSort = 'likes';
        loadMessages();
    });

    // 頁面載入時獲取留言
    loadMessages();
});

